package com.resumeanalyzer.controller;
import com.resumeanalyzer.dto.*; import com.resumeanalyzer.service.AuthService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/auth") @RequiredArgsConstructor public class AuthController { private final AuthService auth; @PostMapping("/register") ResponseEntity<AuthResponse> register(@Valid @RequestBody AuthRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(auth.register(request));} @PostMapping("/login") AuthResponse login(@Valid @RequestBody AuthRequest request){return auth.login(request);} }
